#!/usr/bin/env bash
# Regenerates governance.yaml in this fixture with `watchover forwarder --write` (one forwarder per type).
# Usage: generate.sh [OUT_FILE]   (default: governance.yaml next to this script). pytest checks for drift.
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
wo="$here/../../../../scripts/watchover"
out="${1:-$here/governance.yaml}"
printf '# Generated by generate.sh - do not edit by hand.\nevent_forwarders: {}\n' > "$out"
sed -i 's/^event_forwarders: {}$/event_forwarders:/' "$out"
"$wo" forwarder --write "$out" --name /governance/events/secops-mail --type email --email-to secops@example.com \
  --email-to pam@example.com --preset critical --items-source '/*' --auth-method-source '/*' --include-error
"$wo" forwarder --write "$out" --name /governance/events/siem --type webhook --url https://siem.example.com/akeyless \
  --auth-type bearer-token --preset critical --preset access-requests --auth-method-source '/*' --items-source '/*'
"$wo" forwarder --write "$out" --name /governance/events/pki-slack --type slack --preset certificates \
  --items-source '/pki/*' --runner periodic --every 24
"$wo" forwarder --write "$out" --name /governance/events/ops-teams --type teams --preset operations \
  --gateway-source https://gw.example.com:8000
"$wo" forwarder --write "$out" --name /governance/events/snow --type service_now --host example.service-now.com \
  --auth-type jwt --client-id snow-client --user-email akeyless@example.com --preset rotation --items-source '/*' --disabled
